import { For, Show } from '@pyreon/core'
import { signal } from '@pyreon/reactivity'
import { formatCombo, getRegisteredHotkeys, parseShortcut, useHotkey } from '@pyreon/hotkeys'

// 'g i' is a sequence: format each step
const label = (shortcut: string) =>
  shortcut.split(/\s+/).map((step) => formatCombo(parseShortcut(step))).join(' then ')

export function Shortcuts(props: { openPalette: () => void; goToInbox: () => void }) {
  const open = signal(false)
  useHotkey('mod+k', props.openPalette, { description: 'Command palette' })
  useHotkey('g i', props.goToInbox, { description: 'Go to inbox' })
  useHotkey('?', () => open.set(true), { description: 'Show shortcuts' })
  useHotkey('escape', () => open.set(false), { description: 'Close this list' })

  // getRegisteredHotkeys() is a snapshot: read it each time the list opens
  return (
    <Show when={open}>
      {() => (
        <dl>
          <For each={[...getRegisteredHotkeys()]} by={(h) => h.shortcut}>
            {(h) => (
              <>
                <dt>{label(h.shortcut)}</dt>
                <dd>{h.description}</dd>
              </>
            )}
          </For>
        </dl>
      )}
    </Show>
  )
}

import { elementRef, type VNodeChild } from '@pyreon/core'
import { useHotkey } from '@pyreon/hotkeys'

const Panel = (props: { onClose: () => void; children?: VNodeChild }) => {
  const panel = elementRef<HTMLDivElement>()
  useHotkey('escape', () => props.onClose(), { target: panel })
  return <div ref={panel} tabIndex={-1}>{props.children}</div>
}
